import{_,o as l,c as a,a3 as t}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/83-进入安全型人群的亲密圈，你将成为掌上明珠.md","filePath":"books/attached/83-进入安全型人群的亲密圈，你将成为掌上明珠.md","lastUpdated":1794316978000}'),i={name:"books/attached/83-进入安全型人群的亲密圈，你将成为掌上明珠.md"};function e(o,p,r,s,d,n){return l(),a("div",null,[...p[0]||(p[0]=[t('<h3 id="进入安全型人群的亲密圈-你将成为掌上明珠" tabindex="-1">进入安全型人群的亲密圈，你将成为掌上明珠 <a class="header-anchor" href="#进入安全型人群的亲密圈-你将成为掌上明珠" aria-label="Permalink to &quot;进入安全型人群的亲密圈，你将成为掌上明珠&quot;">​</a></h3><ul><li><p>你的幸福将成为他的头等大事。</p></li><li><p>他会对你绝对信赖。</p></li><li><p>你的决定是最重要的。</p></li><li><p>你会感觉自己受到尊重和保护。</p></li><li><p>你对亲密的需求能得到无限满足。</p></li></ul><p>很多处于焦虑——回避型亲密关系的人，根本不相信“掌上明珠”般呵护的存在，他们觉得所有人都面临着亲密圈的棘手问题。他们甚至觉得，别人只是因为家丑不可外扬而隐瞒事实。但事实上，这种关系一定是存在的，而且并不少见。毕竟安全型依恋风格占到总人口的一半以上，他们对于亲密圈中的人都是十分忠诚体贴的。</p><p>玛莎与克雷格之间那把“冒烟的枪”</p><p>在玛莎与克雷格的关系之初，就已经有种种迹象，预示着玛莎进入了亲密关系的万丈深渊，这些迹象就像是犯罪现场那把冒着烟的枪。</p><ul><li><p>玛莎去田径场给克雷格加油时，克雷格视而不见。</p></li><li><p>克雷格想要对外隐藏他们的恋爱关系。</p></li><li><p>对于玛莎与前任一刀两断的事情，克雷格感觉很震惊，因为他并不想担起严肃的亲密关系这个责任。</p></li><li><p>克雷格会不断贬损玛莎。</p></li><li><p>他将玛莎的短处拿来与“幽灵般的前任”金杰做对比。</p></li><li><p>面对玛莎的担忧与自我怀疑，克雷格选择落井下石。</p></li><li><p>最重要的是，通过这一系列行为，他传达出了一种强烈的信息：他根本没有能力照顾到玛莎的情感需求。</p></li></ul><p>在第5章，有对于“冒烟的枪”这一现象的详细解读。</p>',7)])])}const h=_(i,[["render",e]]);export{u as __pageData,h as default};
